     1	//! Status-change webhooks.
     2	//!
     3	//! When a credential's status flips ([`crate::status::revoke_credential`]),
     4	//! [`Notifier::notify`] sends the change to the relying parties that
     5	//! subscribed to the issuing tenant's changes. A subscription is a tenant
     6	//! setting of kind [`WEBHOOK_KIND`] whose value holds the endpoint `url`.
     7	//!
     8	//! The canary is a platform subscription that receives every change;
     9	//! [`Notifier::canary_healthy`] is the notifier's health check. Every
    10	//! delivery attempt is reported to the [`DeliverySink`].
    11	
    12	use std::sync::atomic::{AtomicBool, Ordering};
    13	use std::sync::{Arc, Mutex};
    14	use std::time::Duration;
    15	
    16	use serde_json::json;
    17	
    18	use crate::settings::{Setting, SettingsStore};
    19	use crate::status::StatusChange;
    20	use crate::webhook::WebhookTransport;
    21	
    22	/// How long one status change may take to fan out.
    23	pub const DISPATCH_BUDGET: Duration = Duration::from_secs(10);
    24	
    25	/// Setting kind of a webhook subscription.
    26	pub const WEBHOOK_KIND: &str = "webhook";
    27	
    28	pub const CANARY_ID: &str = "canary";
    29	pub const CANARY_URL: &str = "https://example.com/webhooks/status";
    30	
    31	#[derive(Debug, Clone, PartialEq, Eq)]
    32	pub struct Subscription {
    33	    pub id: String,
    34	    pub url: String,
    35	}
    36	
    37	impl Subscription {
    38	    pub fn canary() -> Self {
