106	    16	pub const CREDENTIALS_CONTEXT: &str = "https://www.w3.org/2018/credentials/v1";
107	    17	
108	    18	/// One selectively disclosable claim, as handed to the holder at issuance.
109	    19	///
110	    20	/// The credential itself only carries [`Disclosure::digest`] in
111	    21	/// `credentialSubject._sd`; the holder reveals a claim by presenting its
112	    22	/// disclosure next to the credential.
113	    23	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
114	    24	pub struct Disclosure {
115	    25	    pub salt: String,
116	    26	    pub name: String,
117	    27	    pub value: Value,
118	    28	}
119	    29	
120	    30	impl Disclosure {
