122	    32	        Disclosure { salt: random_token(16), name: name.to_string(), value }
123	    33	    }
124	    34	
125	    35	    /// base64url (no padding) of SHA-256 over the canonical `[salt, name, value]` array.
126	    36	    pub fn digest(&self) -> String {
127	    37	        let triple = json!([self.salt, self.name, self.value]);
128	    38	        URL_SAFE_NO_PAD.encode(Sha256::digest(canonicalize(&triple).as_bytes()))
129	    39	    }
130	    40	}
131	    41	
132	    42	/// The bytes a proof signs: the canonical form of `document` without `proof`.
133	    43	pub fn signing_input(document: &Value) -> Vec<u8> {
134	    44	    match document {
135	    45	        Value::Object(map) if map.contains_key("proof") => {
136	    46	            let mut unsigned = map.clone();
137	    47	            unsigned.remove("proof");
138	    48	            canonicalize(&Value::Object(unsigned)).into_bytes()
139	    49	        }
140	    50	        other => canonicalize(other).into_bytes(),
141	    51	    }
142	    52	}
