144	    54	/// Adds (or replaces) an `Ed25519Signature2020` proof on `document`.
145	    55	pub fn sign(document: &mut Value, key: &SigningKey, verification_method: &str, purpose: &str, created: i64) {
146	    56	    let signature = key.sign(&signing_input(document));
147	    57	    document["proof"] = json!({
148	    58	        "type": ED25519_SIGNATURE_2020,
149	    59	        "created": created,
150	    60	        "verificationMethod": verification_method,
151	    61	        "proofPurpose": purpose,
152	    62	        "proofValue": affinidi_encoding::encode_base58btc(&signature.to_bytes()),
153	    63	    });
154	    64	}
