156	    66	/// Checks the `proofValue` of `document` against `key`.
157	    67	pub fn verify_signature(document: &Value, key: &VerifyingKey) -> Result<(), String> {
158	    68	    let proof_value = document
159	    69	        .pointer("/proof/proofValue")
160	    70	        .and_then(Value::as_str)
161	    71	        .ok_or("proof has no proofValue")?;
162	    72	    let bytes = affinidi_encoding::decode_base58btc(proof_value).map_err(|e| format!("proofValue: {e}"))?;
163	    73	    let signature = Signature::from_slice(&bytes).map_err(|e| format!("proofValue: {e}"))?;
164	    74	    key.verify(&signing_input(document), &signature).map_err(|_| "signature does not match".to_string())
