167	    77	/// RFC 8785 JSON Canonicalization Scheme.
168	    78	///
169	    79	/// Object members are ordered by the UTF-16 code units of their names,
170	    80	/// strings use the minimal JSON escaping, and numbers are written the way
171	    81	/// ECMAScript prints them (integral values without a fraction).
172	    82	pub fn canonicalize(value: &Value) -> String {
173	    83	    let mut out = String::new();
174	    84	    write_canonical(value, &mut out);
175	    85	    out
176	    86	}
177	    87	
178	    88	fn write_canonical(value: &Value, out: &mut String) {
179	    89	    match value {
180	    90	        Value::Null | Value::Bool(_) | Value::String(_) => {
181	    91	            out.push_str(&serde_json::to_string(value).expect("scalars serialize"))
182	    92	        }
183	    93	        Value::Number(n) => out.push_str(&canonical_number(n)),
184	    94	        Value::Array(items) => {
185	    95	            out.push('[');
186	    96	            for (i, item) in items.iter().enumerate() {
187	    97	                if i > 0 {
188	    98	                    out.push(',');
189	    99	                }
190	   100	                write_canonical(item, out);
191	   101	            }
192	   102	            out.push(']');
193	   103	        }
194	   104	        Value::Object(map) => {
195	   105	            let mut entries: Vec<(&String, &Value)> = map.iter().collect();
196	   106	            entries.sort_by(|(a, _), (b, _)| a.encode_utf16().cmp(b.encode_utf16()));
197	   107	            out.push('{');
198	   108	            for (i, (key, item)) in entries.into_iter().enumerate() {
199	   109	                if i > 0 {
200	   110	                    out.push(',');
201	   111	                }
202	   112	                out.push_str(&serde_json::to_string(key).expect("keys serialize"));
203	   113	                out.push(':');
204	   114	                write_canonical(item, out);
205	   115	            }
206	   116	            out.push('}');
207	   117	        }
208	   118	    }
209	   119	}
210	   120	
211	   121	fn canonical_number(n: &serde_json::Number) -> String {
212	   122	    if n.is_i64() || n.is_u64() {
213	   123	        return n.to_string();
214	   124	    }
215	   125	    let f = n.as_f64().unwrap_or(0.0);
216	   126	    if f == f.trunc() && f.abs() < 1e21 {
217	   127	        format!("{}", f as i128)
218	   128	    } else {
219	   129	        format!("{f}")
220	   130	    }
221	   131	}
222	   132	
223	   133	/// A random base64url token of `bytes` bytes of entropy.
224	   134	pub fn random_token(bytes: usize) -> String {
225	   135	    let mut buf = vec![0u8; bytes];
226	   136	    getrandom::fill(&mut buf).expect("system randomness");
227	   137	    URL_SAFE_NO_PAD.encode(buf)
228	   138	}
229	   139	
230	   140	/// A random (version 4) `urn:uuid:` identifier.
231	   141	pub fn random_urn() -> String {
232	   142	    let mut b = [0u8; 16];
233	   143	    getrandom::fill(&mut b).expect("system randomness");
234	   144	    b[6] = (b[6] & 0x0f) | 0x40;
235	   145	    b[8] = (b[8] & 0x3f) | 0x80;
236	   146	    let hex: String = b.iter().map(|x| format!("{x:02x}")).collect();
237	   147	    format!("urn:uuid:{}-{}-{}-{}-{}", &hex[0..8], &hex[8..12], &hex[12..16], &hex[16..20], &hex[20..32])
238	   148	}
