676	    78	/// The HTTPS URL a `did:web` document is published at: `did.json` under the
677	    79	/// host's `/.well-known/` directory, with any further segments of the
678	    80	/// identifier as subdirectories. A port is written percent-encoded in the host
679	    81	/// segment (`example.com%3A8443`).
680	    82	pub fn did_web_url(did: &str) -> Result<String, ResolveError> {
681	    83	    let invalid = || ResolveError::InvalidDid(did.to_string());
682	    84	    let id = did.strip_prefix("did:web:").ok_or_else(invalid)?;
683	    85	    let mut segments = id.split(':');
684	    86	    let host = percent_decode(segments.next().unwrap_or_default()).ok_or_else(invalid)?;
685	    87	    if host.is_empty() || host.contains('/') {
686	    88	        return Err(invalid());
687	    89	    }
688	    90	    let path: Vec<String> = segments.map(percent_decode).collect::<Option<_>>().ok_or_else(invalid)?;
689	    91	    if path.iter().any(|s| s.is_empty() || s.contains('/')) {
690	    92	        return Err(invalid());
691	    93	    }
692	    94	    let mut url = format!("https://{host}/.well-known");
693	    95	    for segment in &path {
694	    96	        url.push('/');
695	    97	        url.push_str(segment);
696	    98	    }
697	    99	    url.push_str("/did.json");
698	   100	    Ok(url)
699	   101	}
