701	   103	fn percent_decode(segment: &str) -> Option<String> {
702	   104	    let bytes = segment.as_bytes();
703	   105	    let mut out = Vec::with_capacity(bytes.len());
704	   106	    let mut i = 0;
705	   107	    while i < bytes.len() {
706	   108	        if bytes[i] == b'%' {
707	   109	            let hex = std::str::from_utf8(bytes.get(i + 1..i + 3)?).ok()?;
708	   110	            out.push(u8::from_str_radix(hex, 16).ok()?);
709	   111	            i += 3;
710	   112	        } else {
711	   113	            out.push(bytes[i]);
712	   114	            i += 1;
713	   115	        }
714	   116	    }
715	   117	    String::from_utf8(out).ok()
716	   118	}
