763	   165	    let mut relationships: Map<String, Value> = Map::new();
764	   166	    let mut services = Vec::new();
765	   167	
766	   168	    for element in elements.split('.') {
767	   169	        let mut chars = element.chars();
768	   170	        let purpose = chars.next().ok_or_else(invalid)?;
769	   171	        let body = chars.as_str();
770	   172	        let relationship = match purpose {
771	   173	            'A' => "assertionMethod",
772	   174	            'V' => "authentication",
773	   175	            'E' => "keyAgreement",
774	   176	            'I' => "capabilityInvocation",
775	   177	            'D' => "capabilityDelegation",
776	   178	            'S' => {
777	   179	                let raw = URL_SAFE_NO_PAD.decode(body.trim_end_matches('=')).map_err(|_| invalid())?;
778	   180	                let abbreviated: Value = serde_json::from_slice(&raw).map_err(|_| invalid())?;
779	   181	                let id = match services.len() {
780	   182	                    0 => format!("{did}#service"),
781	   183	                    n => format!("{did}#service-{n}"),
782	   184	                };
783	   185	                let mut service = expand_service(&abbreviated);
784	   186	                service["id"] = json!(id);
785	   187	                services.push(service);
