794	   196	        methods.push(multikey(&vm_id, did, body));
795	   197	        relationships.entry(relationship).or_insert_with(|| json!([])).as_array_mut().unwrap().push(json!(vm_id));
796	   198	    }
797	   199	
798	   200	    let mut document = json!({
799	   201	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
800	   202	        "id": did,
801	   203	        "verificationMethod": methods,
802	   204	        "service": services,
803	   205	    });
