     1	//! The credential wire format: canonical JSON, Ed25519 proofs and
     2	//! selectively disclosable claims.
     3	//!
     4	//! Every signature in the system covers the RFC 8785 (JCS) form of a document
     5	//! with its `proof` member removed, so a document signed by the wallet and
     6	//! verified here (or the other way round) hashes the same bytes on both sides.
     7	
     8	use base64::engine::general_purpose::URL_SAFE_NO_PAD;
     9	use base64::Engine;
    10	use ed25519_dalek::{Signature, Signer, SigningKey, Verifier as _, VerifyingKey};
    11	use serde::{Deserialize, Serialize};
    12	use serde_json::{json, Value};
    13	use sha2::{Digest, Sha256};
    14	
    15	pub const ED25519_SIGNATURE_2020: &str = "Ed25519Signature2020";
    16	pub const CREDENTIALS_CONTEXT: &str = "https://www.w3.org/2018/credentials/v1";
    17	
    18	/// One selectively disclosable claim, as handed to the holder at issuance.
    19	///
    20	/// The credential itself only carries [`Disclosure::digest`] in
    21	/// `credentialSubject._sd`; the holder reveals a claim by presenting its
    22	/// disclosure next to the credential.
    23	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
    24	pub struct Disclosure {
    25	    pub salt: String,
    26	    pub name: String,
    27	    pub value: Value,
    28	}
    29	
    30	impl Disclosure {
    31	    pub fn new(name: &str, value: Value) -> Self {
    32	        Disclosure { salt: random_token(16), name: name.to_string(), value }
    33	    }
    34	
    35	    /// base64url (no padding) of SHA-256 over the canonical `[salt, name, value]` array.
    36	    pub fn digest(&self) -> String {
    37	        let triple = json!([self.salt, self.name, self.value]);
    38	        URL_SAFE_NO_PAD.encode(Sha256::digest(canonicalize(&triple).as_bytes()))
    39	    }
    40	}
    41	
    42	/// The bytes a proof signs: the canonical form of `document` without `proof`.
    43	pub fn signing_input(document: &Value) -> Vec<u8> {
    44	    match document {
    45	        Value::Object(map) if map.contains_key("proof") => {
    46	            let mut unsigned = map.clone();
    47	            unsigned.remove("proof");
    48	            canonicalize(&Value::Object(unsigned)).into_bytes()
    49	        }
    50	        other => canonicalize(other).into_bytes(),
    51	    }
    52	}
    53	
    54	/// Adds (or replaces) an `Ed25519Signature2020` proof on `document`.
    55	pub fn sign(document: &mut Value, key: &SigningKey, verification_method: &str, purpose: &str, created: i64) {
    56	    let signature = key.sign(&signing_input(document));
    57	    document["proof"] = json!({
    58	        "type": ED25519_SIGNATURE_2020,
    59	        "created": created,
    60	        "verificationMethod": verification_method,
    61	        "proofPurpose": purpose,
    62	        "proofValue": affinidi_encoding::encode_base58btc(&signature.to_bytes()),
    63	    });
    64	}
    65	
    66	/// Checks the `proofValue` of `document` against `key`.
    67	pub fn verify_signature(document: &Value, key: &VerifyingKey) -> Result<(), String> {
    68	    let proof_value = document
    69	        .pointer("/proof/proofValue")
    70	        .and_then(Value::as_str)
    71	        .ok_or("proof has no proofValue")?;
    72	    let bytes = affinidi_encoding::decode_base58btc(proof_value).map_err(|e| format!("proofValue: {e}"))?;
    73	    let signature = Signature::from_slice(&bytes).map_err(|e| format!("proofValue: {e}"))?;
    74	    key.verify(&signing_input(document), &signature).map_err(|_| "signature does not match".to_string())
    75	}
    76	
    77	/// RFC 8785 JSON Canonicalization Scheme.
    78	///
    79	/// Object members are ordered by the UTF-16 code units of their names,
    80	/// strings use the minimal JSON escaping, and numbers are written the way
    81	/// ECMAScript prints them (integral values without a fraction).
    82	pub fn canonicalize(value: &Value) -> String {
    83	    let mut out = String::new();
    84	    write_canonical(value, &mut out);
    85	    out
    86	}
    87	
    88	fn write_canonical(value: &Value, out: &mut String) {
    89	    match value {
    90	        Value::Null | Value::Bool(_) | Value::String(_) => {
    91	            out.push_str(&serde_json::to_string(value).expect("scalars serialize"))
    92	        }
    93	        Value::Number(n) => out.push_str(&canonical_number(n)),
    94	        Value::Array(items) => {
    95	            out.push('[');
    96	            for (i, item) in items.iter().enumerate() {
    97	                if i > 0 {
    98	                    out.push(',');
    99	                }
   100	                write_canonical(item, out);
   101	            }
   102	            out.push(']');
   103	        }
   104	        Value::Object(map) => {
   105	            let mut entries: Vec<(&String, &Value)> = map.iter().collect();
   106	            entries.sort_by(|(a, _), (b, _)| a.encode_utf16().cmp(b.encode_utf16()));
   107	            out.push('{');
   108	            for (i, (key, item)) in entries.into_iter().enumerate() {
   109	                if i > 0 {
   110	                    out.push(',');
   111	                }
   112	                out.push_str(&serde_json::to_string(key).expect("keys serialize"));
   113	                out.push(':');
   114	                write_canonical(item, out);
   115	            }
   116	            out.push('}');
   117	        }
   118	    }
   119	}
   120	
   121	fn canonical_number(n: &serde_json::Number) -> String {
   122	    if n.is_i64() || n.is_u64() {
   123	        return n.to_string();
   124	    }
   125	    let f = n.as_f64().unwrap_or(0.0);
   126	    if f == f.trunc() && f.abs() < 1e21 {
   127	        format!("{}", f as i128)
   128	    } else {
   129	        format!("{f}")
   130	    }
   131	}
   132	
   133	/// A random base64url token of `bytes` bytes of entropy.
   134	pub fn random_token(bytes: usize) -> String {
   135	    let mut buf = vec![0u8; bytes];
   136	    getrandom::fill(&mut buf).expect("system randomness");
   137	    URL_SAFE_NO_PAD.encode(buf)
   138	}
   139	
   140	/// A random (version 4) `urn:uuid:` identifier.
   141	pub fn random_urn() -> String {
   142	    let mut b = [0u8; 16];
   143	    getrandom::fill(&mut b).expect("system randomness");
   144	    b[6] = (b[6] & 0x0f) | 0x40;
   145	    b[8] = (b[8] & 0x3f) | 0x80;
   146	    let hex: String = b.iter().map(|x| format!("{x:02x}")).collect();
   147	    format!("urn:uuid:{}-{}-{}-{}-{}", &hex[0..8], &hex[8..12], &hex[12..16], &hex[16..20], &hex[20..32])
   148	}
