    74	/// An onboarded issuer's signing identity.
    75	pub struct Issuer {
    76	    did: String,
    77	    verification_method: String,
    78	    key: SigningKey,
    79	}
    80	
    81	impl Issuer {
    82	    /// `verification_method` is the DID URL of the key in the issuer's document.
    83	    pub fn new(did: &str, verification_method: &str, seed: &[u8; 32]) -> Self {
    84	        Issuer {
    85	            did: did.to_string(),
    86	            verification_method: verification_method.to_string(),
    87	            key: SigningKey::from_bytes(seed),
    88	        }
    89	    }
    90	
    91	    pub fn did(&self) -> &str {
    92	        &self.did
    93	    }
    94	
    95	    pub fn verifying_key(&self) -> VerifyingKey {
    96	        self.key.verifying_key()
    97	    }
    98	
    99	    /// The status list this issuer's credentials are indexed into.
   100	    pub fn status_list(&self) -> String {
   101	        format!("{}#revocation", self.did)
   102	    }
   103	
   104	    pub fn issue(&self, store: &Store, request: &CredentialRequest) -> Result<IssuedCredential, IssueError> {
   105	        let holder_key = request.holder.strip_prefix("did:key:").unwrap_or_default();
   106	        match affinidi_encoding::decode_multikey_with_codec(holder_key) {
   107	            Ok((affinidi_encoding::ED25519_PUB, _)) => {}
   108	            _ => return Err(IssueError::InvalidHolder(request.holder.clone())),
   109	        }
   110	        let not_before = request.not_before.unwrap_or(request.issued_at);
   111	        if request.expires_at < not_before {
   112	            return Err(IssueError::InvalidValidity);
   113	        }
   114	
   115	        let disclosures: Vec<Disclosure> =
   116	            request.claims.iter().map(|(name, value)| Disclosure::new(name, value.clone())).collect();
   117	        let mut digests: Vec<String> = disclosures.iter().map(Disclosure::digest).collect();
   118	        digests.sort();
   119	
   120	        let status_list = self.status_list();
   121	        let status_index =
   122	            store.allocate_status_index(&status_list).ok_or_else(|| IssueError::StatusListFull(status_list.clone()))?;
   123	
   124	        let id = credential::random_urn();
   125	        let mut vc = json!({
   126	            "@context": [CREDENTIALS_CONTEXT],
   127	            "id": id,
   128	            "type": ["VerifiableCredential", request.credential_type],
   129	            "issuer": self.did,
   130	            "issued_at": request.issued_at,
   131	            "not_before": not_before,
   132	            "expires_at": request.expires_at,
   133	            "credentialSubject": { "id": request.holder, "_sd": digests },
   134	            "credentialStatus": {
   135	                "type": "StatusListEntry",
   136	                "statusListId": status_list,
   137	                "statusListIndex": status_index,
   138	            },
   139	        });
   140	        credential::sign(&mut vc, &self.key, &self.verification_method, "assertionMethod", request.issued_at);
   141	
   142	        store.record_credential(CredentialRecord {
   143	            id,
   144	            issuer: self.did.clone(),
   145	            subject: request.holder.clone(),
   146	            status_list,
   147	            status_index,
   148	            expires_at: request.expires_at,
   149	        });
   150	        Ok(IssuedCredential { credential: vc, disclosures })
   151	    }
   152	}
