    31	    #[error("document for {did} is not a valid DID document: {reason}")]
    32	    InvalidDocument { did: String, reason: String },
    33	    #[error("document fetched for {did} is for {found}")]
    34	    DocumentMismatch { did: String, found: String },
    35	}
    36	
    37	#[derive(Clone)]
    38	pub struct Resolver {
    39	    transport: Arc<dyn DocumentTransport>,
    40	}
    41	
    42	impl Resolver {
    43	    pub fn new(transport: Arc<dyn DocumentTransport>) -> Self {
    44	        Resolver { transport }
    45	    }
    46	
    47	    pub fn resolve(&self, did: &str) -> Result<Document, ResolveError> {
    48	        let method = did
    49	            .strip_prefix("did:")
    50	            .and_then(|rest| rest.split_once(':'))
    51	            .map(|(method, _)| method)
    52	            .ok_or_else(|| ResolveError::InvalidDid(did.to_string()))?;
    53	        match method {
    54	            "key" => resolve_key(did),
    55	            "peer" => resolve_peer(did),
    56	            "web" => self.resolve_web(did),
    57	            other => Err(ResolveError::UnsupportedMethod(other.to_string())),
    58	        }
    59	    }
    60	
    61	    fn resolve_web(&self, did: &str) -> Result<Document, ResolveError> {
    62	        let url = did_web_url(did)?;
    63	        let body = self.transport.get(&url)?;
    64	        let document: Document = serde_json::from_slice(&body)
    65	            .map_err(|e| ResolveError::InvalidDocument { did: did.to_string(), reason: e.to_string() })?;
    66	        if document.id.as_str() != did {
    67	            return Err(ResolveError::DocumentMismatch { did: did.to_string(), found: document.id.to_string() });
    68	        }
    69	        Ok(document)
    70	    }
    71	}
    72	
    73	/// The `did:key` identifier for an Ed25519 public key.
    74	pub fn did_key_for(key: &VerifyingKey) -> String {
    75	    format!("did:key:{}", affinidi_encoding::encode_multikey(affinidi_encoding::ED25519_PUB, key.as_bytes()))
    76	}
    77	
    78	/// The HTTPS URL a `did:web` document is published at: `did.json` under the
    79	/// host's `/.well-known/` directory, with any further segments of the
    80	/// identifier as subdirectories. A port is written percent-encoded in the host
    81	/// segment (`example.com%3A8443`).
    82	pub fn did_web_url(did: &str) -> Result<String, ResolveError> {
    83	    let invalid = || ResolveError::InvalidDid(did.to_string());
    84	    let id = did.strip_prefix("did:web:").ok_or_else(invalid)?;
    85	    let mut segments = id.split(':');
    86	    let host = percent_decode(segments.next().unwrap_or_default()).ok_or_else(invalid)?;
    87	    if host.is_empty() || host.contains('/') {
    88	        return Err(invalid());
    89	    }
    90	    let path: Vec<String> = segments.map(percent_decode).collect::<Option<_>>().ok_or_else(invalid)?;
    91	    if path.iter().any(|s| s.is_empty() || s.contains('/')) {
    92	        return Err(invalid());
    93	    }
    94	    let mut url = format!("https://{host}/.well-known");
    95	    for segment in &path {
    96	        url.push('/');
    97	        url.push_str(segment);
    98	    }
    99	    url.push_str("/did.json");
   100	    Ok(url)
   101	}
   102	
   103	fn percent_decode(segment: &str) -> Option<String> {
   104	    let bytes = segment.as_bytes();
   105	    let mut out = Vec::with_capacity(bytes.len());
   106	    let mut i = 0;
   107	    while i < bytes.len() {
   108	        if bytes[i] == b'%' {
   109	            let hex = std::str::from_utf8(bytes.get(i + 1..i + 3)?).ok()?;
   110	            out.push(u8::from_str_radix(hex, 16).ok()?);
   111	            i += 3;
   112	        } else {
   113	            out.push(bytes[i]);
   114	            i += 1;
   115	        }
   116	    }
   117	    String::from_utf8(out).ok()
   118	}
   119	
   120	fn resolve_key(did: &str) -> Result<Document, ResolveError> {
   121	    let multibase = did.strip_prefix("did:key:").unwrap_or_default();
   122	    single_key_document(did, multibase)
   123	}
   124	
   125	fn resolve_peer(did: &str) -> Result<Document, ResolveError> {
   126	    let id = did.strip_prefix("did:peer:").unwrap_or_default();
   127	    if let Some(multibase) = id.strip_prefix('0') {
   128	        single_key_document(did, multibase)
   129	    } else if let Some(elements) = id.strip_prefix("2.") {
   130	        peer_2_document(did, elements)
   131	    } else {
   132	        Err(ResolveError::InvalidDid(did.to_string()))
   133	    }
   134	}
   135	
   136	/// Checks that `multibase` is an Ed25519 multikey.
   137	fn ed25519_multikey(did: &str, multibase: &str) -> Result<(), ResolveError> {
   138	    match affinidi_encoding::decode_multikey_with_codec(multibase) {
   139	        Ok((affinidi_encoding::ED25519_PUB, bytes)) if bytes.len() == 32 => Ok(()),
   140	        _ => Err(ResolveError::InvalidDid(did.to_string())),
   141	    }
   142	}
   143	
   144	fn multikey(id: &str, controller: &str, multibase: &str) -> Value {
   145	    json!({ "id": id, "type": "Multikey", "controller": controller, "publicKeyMultibase": multibase })
   146	}
   147	
   148	fn single_key_document(did: &str, multibase: &str) -> Result<Document, ResolveError> {
   149	    ed25519_multikey(did, multibase)?;
   150	    let vm_id = format!("{did}#{multibase}");
   151	    to_document(did, json!({
   152	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
   153	        "id": did,
   154	        "verificationMethod": [multikey(&vm_id, did, multibase)],
   155	        "authentication": [vm_id],
   156	        "assertionMethod": [vm_id],
   157	        "capabilityInvocation": [vm_id],
   158	        "capabilityDelegation": [vm_id],
   159	    }))
   160	}
   161	
   162	fn peer_2_document(did: &str, elements: &str) -> Result<Document, ResolveError> {
   163	    let invalid = || ResolveError::InvalidDid(did.to_string());
   164	    let mut methods = Vec::new();
   165	    let mut relationships: Map<String, Value> = Map::new();
   166	    let mut services = Vec::new();
   167	
   168	    for element in elements.split('.') {
   169	        let mut chars = element.chars();
   170	        let purpose = chars.next().ok_or_else(invalid)?;
   171	        let body = chars.as_str();
   172	        let relationship = match purpose {
   173	            'A' => "assertionMethod",
   174	            'V' => "authentication",
   175	            'E' => "keyAgreement",
   176	            'I' => "capabilityInvocation",
   177	            'D' => "capabilityDelegation",
   178	            'S' => {
   179	                let raw = URL_SAFE_NO_PAD.decode(body.trim_end_matches('=')).map_err(|_| invalid())?;
   180	                let abbreviated: Value = serde_json::from_slice(&raw).map_err(|_| invalid())?;
   181	                let id = match services.len() {
   182	                    0 => format!("{did}#service"),
   183	                    n => format!("{did}#service-{n}"),
   184	                };
   185	                let mut service = expand_service(&abbreviated);
   186	                service["id"] = json!(id);
   187	                services.push(service);
   188	                continue;
   189	            }
   190	            _ => return Err(invalid()),
   191	        };
   192	        if purpose != 'E' {
   193	            ed25519_multikey(did, body)?;
   194	        }
   195	        let vm_id = format!("{did}#key-{}", methods.len() + 1);
   196	        methods.push(multikey(&vm_id, did, body));
   197	        relationships.entry(relationship).or_insert_with(|| json!([])).as_array_mut().unwrap().push(json!(vm_id));
   198	    }
   199	
   200	    let mut document = json!({
   201	        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
   202	        "id": did,
   203	        "verificationMethod": methods,
   204	        "service": services,
   205	    });
   206	    for (relationship, ids) in relationships {
   207	        document[relationship] = ids;
   208	    }
   209	    to_document(did, document)
   210	}
   211	
   212	/// Expands the abbreviated keys peer:2 uses for services (`t`, `s`, `r`, `a`, `dm`).
   213	fn expand_service(value: &Value) -> Value {
   214	    match value {
   215	        Value::Object(map) => Value::Object(
   216	            map.iter()
   217	                .map(|(k, v)| {
   218	                    let key = match k.as_str() {
   219	                        "t" => "type",
   220	                        "s" => "serviceEndpoint",
   221	                        "r" => "routingKeys",
   222	                        "a" => "accept",
   223	                        other => other,
   224	                    };
   225	                    (key.to_string(), expand_service(v))
   226	                })
   227	                .collect(),
   228	        ),
   229	        Value::String(s) if s == "dm" => json!("DIDCommMessaging"),
   230	        Value::Array(items) => Value::Array(items.iter().map(expand_service).collect()),
   231	        other => other.clone(),
   232	    }
   233	}
   234	
   235	fn to_document(did: &str, value: Value) -> Result<Document, ResolveError> {
   236	    serde_json::from_value(value)
   237	        .map_err(|e| ResolveError::InvalidDocument { did: did.to_string(), reason: e.to_string() })
   238	}
