    50	    /// A store holding every issuer in `data/onboarded-issuers.json`.
    51	    pub fn from_onboarding_data() -> Result<Self, serde_json::Error> {
    52	        let issuers: Vec<OnboardedIssuer> = serde_json::from_str(ONBOARDING_DATA)?;
