   110	        self.lock().status_lists.get(list).map(|status| status.is_set(index))
   111	    }
   112	
   113	    /// The published form of `list`.
   114	    pub fn encoded_status_list(&self, list: &str) -> Option<String> {
   115	        self.lock().status_lists.get(list).map(StatusList::encode)
   116	    }
   117	}
