    42	    /// The mirror at `$DID_MIRROR_ROOT`, or the checked-in copy of the bucket.
    43	    pub fn from_env() -> Self {
    44	        match std::env::var_os("DID_MIRROR_ROOT") {
    45	            Some(root) => MirrorTransport::new(root),
    46	            None => MirrorTransport::new(Path::new(env!("CARGO_MANIFEST_DIR")).join("../reference/infra/hosted-dids")),
    47	        }
    48	    }
    49	
    50	    fn path_for(&self, url: &str) -> Result<PathBuf, TransportError> {
    51	        let invalid = || TransportError::InvalidUrl(url.to_string());
    52	        let parsed = Url::parse(url).map_err(|_| invalid())?;
    53	        if parsed.scheme() != "https" || url.contains("/../") {
    54	            return Err(invalid());
    55	        }
    56	        let host = parsed.host_str().ok_or_else(invalid)?;
    57	        let authority = match parsed.port() {
    58	            Some(port) => format!("{host}:{port}"),
    59	            None => host.to_string(),
    60	        };
    61	        let mut path = self.root.join(authority);
    62	        for segment in parsed.path_segments().into_iter().flatten() {
    63	            let segment = Path::new(segment);
    64	            if segment.components().any(|c| !matches!(c, Component::Normal(_))) {
    65	                return Err(invalid());
    66	            }
    67	            path.push(segment);
    68	        }
    69	        Ok(path)
    70	    }
    71	}
    72	
    73	impl DocumentTransport for MirrorTransport {
    74	    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
    75	        let path = self.path_for(url)?;
    76	        std::fs::read(&path).map_err(|e| match e.kind() {
    77	            std::io::ErrorKind::NotFound => TransportError::NotFound(url.to_string()),
    78	            _ => TransportError::Io { url: url.to_string(), reason: e.to_string() },
    79	        })
    80	    }
    81	}
