    12	fn revoked(issuer: &str, index: usize) -> StatusChange {
    13	    StatusChange {
    14	        credential_id: format!("urn:uuid:00000000-0000-4000-8000-{index:012}"),
    15	        issuer: issuer.to_string(),
    16	        status_list: format!("{issuer}#revocation"),
