    30	  /// Requests a [credentialType] credential for this holder and keeps it.
    31	  Future<HeldCredential> requestCredential(String credentialType) async {
    32	    final did = holderKey().did;
    33	    final credential = await _issuer.issue(
    34	      holderDid: did,
    35	      credentialType: credentialType,
    36	    );
