    15	    // U+1F600 is a surrogate pair (0xD83D..) and sorts before U+FB01 in UTF-16,
    16	    // although its UTF-8 encoding sorts after.
    17	    let value = json!({ "\u{FB01}": 1, "\u{1F600}": 2, "a": 3 });
    18	    assert_eq!(canonicalize(&value), "{\"a\":3,\"\u{1F600}\":2,\"\u{FB01}\":1}");
