    22	fn subscribe(settings: &SettingsStore, tenant: &str, id: &str, url: &str) {
    23	    settings.put(Setting::new(tenant, &format!("webhook/{id}"), WEBHOOK_KIND, json!({ "url": url })));
    24	}
