    26	/// A tenant as most clubs look: a handful of preferences and a few relying
    27	/// parties listening for status changes.
    28	fn small_tenant(settings: &SettingsStore, transport: &HermeticTransport, tenant: &str, host: &str) -> Vec<String> {
    29	    for i in 0..12 {
    30	        settings.put(Setting::new(tenant, &format!("pref/{i:02}"), "preference", json!({ "n": i })));
    31	    }
    32	    (1..=3)
    33	        .map(|i| {
    34	            let url = format!("https://{host}/hooks/{i}");
    35	            subscribe(settings, tenant, &format!("rp-{i}"), &url);
    36	            transport.route(&url, Endpoint::ok());
    37	            url
    38	        })
    39	        .collect()
    40	}
